INSERT INTO public.tests (
  id, name, category, related_syndrome, description,
  question_count, duration_minutes,
  is_recommended, is_coming_soon,
  is_integrated, is_free, price_krw,
  subdomains, questions
) VALUES (
  'A-4',
  '실패공포 증후군 검사',
  'A',
  '실패공포 증후군',
  '실패에 대한 두려움이 학습과 도전을 회피하게 만드는 정도를 측정합니다.',
  20,
  3,
  false,
  false,
  false,
  false,
  2900,
  '["완벽주의 압박형 (Perfectionism Pressure Type)","평가 회피형 (Evaluation Avoidance Type)","자존감 조건형 (Self-Esteem Contingent Type)","자기조절 결핍형 (Self-Control Deficiency Type)"]'::jsonb,
  '[{"id":1,"text":"한 문제라도 틀리면 전부 망한 것처럼 느껴진다.","subdomain":"완벽주의 압박형 (Perfectionism Pressure Type)","subdomainEn":"Perfectionism Pressure Type","isReversed":false},{"id":2,"text":"다른 사람보다 완벽해야만 안심이 된다.","subdomain":"완벽주의 압박형 (Perfectionism Pressure Type)","subdomainEn":"Perfectionism Pressure Type","isReversed":false},{"id":3,"text":"실수하는 자신을 용납하기 어렵다.","subdomain":"완벽주의 압박형 (Perfectionism Pressure Type)","subdomainEn":"Perfectionism Pressure Type","isReversed":false},{"id":4,"text":"\"완벽하지 않으면 실패다\"라는 생각이 자주 든다.","subdomain":"완벽주의 압박형 (Perfectionism Pressure Type)","subdomainEn":"Perfectionism Pressure Type","isReversed":false},{"id":5,"text":"시험 준비 중 계획대로 안 되면 스스로에게 화가 난다.","subdomain":"완벽주의 압박형 (Perfectionism Pressure Type)","subdomainEn":"Perfectionism Pressure Type","isReversed":false},{"id":6,"text":"잘할 자신이 없으면 시도조차 하기 싫다.","subdomain":"평가 회피형 (Evaluation Avoidance Type)","subdomainEn":"Evaluation Avoidance Type","isReversed":false},{"id":7,"text":"결과가 나쁠까 봐 아예 응시를 피하고 싶을 때가 있다.","subdomain":"평가 회피형 (Evaluation Avoidance Type)","subdomainEn":"Evaluation Avoidance Type","isReversed":false},{"id":8,"text":"실패할 가능성이 보이면 차라리 포기하는 편이다.","subdomain":"평가 회피형 (Evaluation Avoidance Type)","subdomainEn":"Evaluation Avoidance Type","isReversed":false},{"id":9,"text":"누군가 내 성적을 평가할 상황을 불편하게 느낀다.","subdomain":"평가 회피형 (Evaluation Avoidance Type)","subdomainEn":"Evaluation Avoidance Type","isReversed":false},{"id":10,"text":"도전보다는 안전한 선택을 선호한다.","subdomain":"평가 회피형 (Evaluation Avoidance Type)","subdomainEn":"Evaluation Avoidance Type","isReversed":false},{"id":11,"text":"실패하면 내 존재가치가 낮아지는 것 같다.","subdomain":"자존감 조건형 (Self-Esteem Contingent Type)","subdomainEn":"Self-Esteem Contingent Type","isReversed":false},{"id":12,"text":"결과가 좋지 않으면 \"나는 부족한 사람\"이라 느낀다.","subdomain":"자존감 조건형 (Self-Esteem Contingent Type)","subdomainEn":"Self-Esteem Contingent Type","isReversed":false},{"id":13,"text":"성적이 곧 나 자신을 증명한다고 생각한다.","subdomain":"자존감 조건형 (Self-Esteem Contingent Type)","subdomainEn":"Self-Esteem Contingent Type","isReversed":false},{"id":14,"text":"다른 사람보다 뒤처지면 수치심이 든다.","subdomain":"자존감 조건형 (Self-Esteem Contingent Type)","subdomainEn":"Self-Esteem Contingent Type","isReversed":false},{"id":15,"text":"성취가 없으면 나를 좋아하기 어렵다.","subdomain":"자존감 조건형 (Self-Esteem Contingent Type)","subdomainEn":"Self-Esteem Contingent Type","isReversed":false},{"id":16,"text":"실패 후 쉽게 자포자기하게 된다.","subdomain":"자기조절 결핍형 (Self-Control Deficiency Type)","subdomainEn":"Self-Control Deficiency Type","isReversed":false},{"id":17,"text":"잘 안되면 감정이 폭발하거나 무기력해진다.","subdomain":"자기조절 결핍형 (Self-Control Deficiency Type)","subdomainEn":"Self-Control Deficiency Type","isReversed":false},{"id":18,"text":"실패 경험이 있으면 이후 도전을 꺼리게 된다.","subdomain":"자기조절 결핍형 (Self-Control Deficiency Type)","subdomainEn":"Self-Control Deficiency Type","isReversed":false},{"id":19,"text":"실패 후 불안감이 오래 지속된다.","subdomain":"자기조절 결핍형 (Self-Control Deficiency Type)","subdomainEn":"Self-Control Deficiency Type","isReversed":false},{"id":20,"text":"실패를 겪으면 \"다시는 못하겠다\"는 생각이 든다.","subdomain":"자기조절 결핍형 (Self-Control Deficiency Type)","subdomainEn":"Self-Control Deficiency Type","isReversed":false}]'::jsonb
)
