INSERT INTO public.tests (
  id, name, category, related_syndrome, description,
  question_count, duration_minutes,
  is_recommended, is_coming_soon,
  is_integrated, is_free, price_krw,
  subdomains, questions
) VALUES (
  'A-5',
  '자기비하 증후군 검사',
  'A',
  '자기비하 증후군',
  '자기 가치에 대한 부정적 인식과 자기비하적 사고 패턴을 측정합니다.',
  20,
  3,
  false,
  false,
  false,
  false,
  2900,
  '["낮은 자존감 (Low Self-Esteem)","부정적 자기대화 (Negative Self-Talk)","비교 열등감 (Comparative Inferiority)","실패 과잉일반화 (Failure Overgeneralization)"]'::jsonb,
  '[{"id":1,"text":"나는 다른 사람보다 능력이 부족하다고 느낀다.","subdomain":"낮은 자존감 (Low Self-Esteem)","subdomainEn":"Low Self-Esteem","isReversed":false},{"id":2,"text":"내가 노력해도 결국 큰 성과를 내기 어렵다고 생각한다.","subdomain":"낮은 자존감 (Low Self-Esteem)","subdomainEn":"Low Self-Esteem","isReversed":false},{"id":3,"text":"나 자신에게 만족하는 순간이 거의 없다.","subdomain":"낮은 자존감 (Low Self-Esteem)","subdomainEn":"Low Self-Esteem","isReversed":false},{"id":4,"text":"내 의견이나 생각은 별로 중요하지 않다고 느낀다.","subdomain":"낮은 자존감 (Low Self-Esteem)","subdomainEn":"Low Self-Esteem","isReversed":false},{"id":5,"text":"나 같은 사람은 성공하기 어렵다고 생각한다.","subdomain":"낮은 자존감 (Low Self-Esteem)","subdomainEn":"Low Self-Esteem","isReversed":false},{"id":6,"text":"실수하면 \"역시 난 안돼\"라는 생각이 든다.","subdomain":"부정적 자기대화 (Negative Self-Talk)","subdomainEn":"Negative Self-Talk","isReversed":false},{"id":7,"text":"마음 속에서 스스로를 자주 비난한다.","subdomain":"부정적 자기대화 (Negative Self-Talk)","subdomainEn":"Negative Self-Talk","isReversed":false},{"id":8,"text":"공부 중에 \"나는 머리가 나빠서 안돼\"라고 자주 느낀다.","subdomain":"부정적 자기대화 (Negative Self-Talk)","subdomainEn":"Negative Self-Talk","isReversed":false},{"id":9,"text":"실패했을 때 자신에게 가혹한 말을 한다.","subdomain":"부정적 자기대화 (Negative Self-Talk)","subdomainEn":"Negative Self-Talk","isReversed":false},{"id":10,"text":"내 안의 목소리가 나를 자주 비판한다.","subdomain":"부정적 자기대화 (Negative Self-Talk)","subdomainEn":"Negative Self-Talk","isReversed":false},{"id":11,"text":"친구들의 성과를 보면 나 자신이 초라하게 느껴진다.","subdomain":"비교 열등감 (Comparative Inferiority)","subdomainEn":"Comparative Inferiority","isReversed":false},{"id":12,"text":"다른 사람은 다 잘하는데 나만 부족하다고 생각한다.","subdomain":"비교 열등감 (Comparative Inferiority)","subdomainEn":"Comparative Inferiority","isReversed":false},{"id":13,"text":"SNS나 소문으로 남의 공부 소식을 들으면 위축된다.","subdomain":"비교 열등감 (Comparative Inferiority)","subdomainEn":"Comparative Inferiority","isReversed":false},{"id":14,"text":"나보다 잘하는 사람을 보면 나의 가치가 줄어드는 기분이 든다.","subdomain":"비교 열등감 (Comparative Inferiority)","subdomainEn":"Comparative Inferiority","isReversed":false},{"id":15,"text":"남의 칭찬을 들을 때 부럽기보다 스스로 작아진다.","subdomain":"비교 열등감 (Comparative Inferiority)","subdomainEn":"Comparative Inferiority","isReversed":false},{"id":16,"text":"한번 실패하면 모든 노력이 무의미하게 느껴진다.","subdomain":"실패 과잉일반화 (Failure Overgeneralization)","subdomainEn":"Failure Overgeneralization","isReversed":false},{"id":17,"text":"시험에서 실수하면 내 인생 전체가 망한 것 같다고 느껴진다.","subdomain":"실패 과잉일반화 (Failure Overgeneralization)","subdomainEn":"Failure Overgeneralization","isReversed":false},{"id":18,"text":"결과가 나쁘면 \"나는 항상 이런 식이야\"라고 생각한다.","subdomain":"실패 과잉일반화 (Failure Overgeneralization)","subdomainEn":"Failure Overgeneralization","isReversed":false},{"id":19,"text":"한번의 실패를 반복해서 떠올리며 자책한다.","subdomain":"실패 과잉일반화 (Failure Overgeneralization)","subdomainEn":"Failure Overgeneralization","isReversed":false},{"id":20,"text":"성적이 낮으면 ''나는 원래 그런 사람''이라고 단정한다.","subdomain":"실패 과잉일반화 (Failure Overgeneralization)","subdomainEn":"Failure Overgeneralization","isReversed":false}]'::jsonb
)
