INSERT INTO public.tests (
  id, name, category, related_syndrome, description,
  question_count, duration_minutes,
  is_recommended, is_coming_soon,
  is_integrated, is_free, price_krw,
  subdomains, questions
) VALUES (
  'A-6',
  '학습 강박 증후군 검사',
  'A',
  '학습 강박 증후군',
  '학습에 대한 강박적 태도와 쉬지 못하는 불안 수준을 측정합니다.',
  20,
  3,
  false,
  false,
  false,
  false,
  2900,
  '["불안 기반 몰입 (Anxiety-Based Immersion)","휴식 죄책감 (Rest Guilt)","통제력 상실 (Loss of Control)","학습 자기동일시 (Self-Identification with Study)"]'::jsonb,
  '[{"id":1,"text":"공부를 멈추면 불안하거나 초조해진다.","subdomain":"불안 기반 몰입 (Anxiety-Based Immersion)","subdomainEn":"Anxiety-Based Immersion","isReversed":false},{"id":2,"text":"쉬는 시간에도 공부 생각이 머릿속에서 떠나지 않는다.","subdomain":"불안 기반 몰입 (Anxiety-Based Immersion)","subdomainEn":"Anxiety-Based Immersion","isReversed":false},{"id":3,"text":"공부를 하지 않으면 뒤처질까 두렵다.","subdomain":"불안 기반 몰입 (Anxiety-Based Immersion)","subdomainEn":"Anxiety-Based Immersion","isReversed":false},{"id":4,"text":"성적이 조금이라도 떨어지면 큰 위기의식이 든다.","subdomain":"불안 기반 몰입 (Anxiety-Based Immersion)","subdomainEn":"Anxiety-Based Immersion","isReversed":false},{"id":5,"text":"공부하지 않는 나 자신이 싫을때가 많다.","subdomain":"불안 기반 몰입 (Anxiety-Based Immersion)","subdomainEn":"Anxiety-Based Immersion","isReversed":false},{"id":6,"text":"쉴 때마다 ''이러면 안된다''는 생각이 든다.","subdomain":"휴식 죄책감 (Rest Guilt)","subdomainEn":"Rest Guilt","isReversed":false},{"id":7,"text":"잠을 자거나 TV를 보면 불안해진다.","subdomain":"휴식 죄책감 (Rest Guilt)","subdomainEn":"Rest Guilt","isReversed":false},{"id":8,"text":"친구를 만나면 ''이 시간에 공부해야 하는데''라는 생각이 든다.","subdomain":"휴식 죄책감 (Rest Guilt)","subdomainEn":"Rest Guilt","isReversed":false},{"id":9,"text":"하루 계획을 다 못 지키면 죄책감이 크다.","subdomain":"휴식 죄책감 (Rest Guilt)","subdomainEn":"Rest Guilt","isReversed":false},{"id":10,"text":"공부를 안하면 스스로를 나무란다.","subdomain":"휴식 죄책감 (Rest Guilt)","subdomainEn":"Rest Guilt","isReversed":false},{"id":11,"text":"공부를 그만두고 싶어도 멈출 수 없다.","subdomain":"통제력 상실 (Loss of Control)","subdomainEn":"Loss of Control","isReversed":false},{"id":12,"text":"피곤해도 계속 공부를 이어가야 마음이 편하다.","subdomain":"통제력 상실 (Loss of Control)","subdomainEn":"Loss of Control","isReversed":false},{"id":13,"text":"계획을 과도하게 세우고 지키지 못하면 스트레스 받는다.","subdomain":"통제력 상실 (Loss of Control)","subdomainEn":"Loss of Control","isReversed":false},{"id":14,"text":"공부를 하지 않으면 무언가 잘못된 기분이 든다.","subdomain":"통제력 상실 (Loss of Control)","subdomainEn":"Loss of Control","isReversed":false},{"id":15,"text":"공부량이 줄면 스스로에 대한 불만이 커진다.","subdomain":"통제력 상실 (Loss of Control)","subdomainEn":"Loss of Control","isReversed":false},{"id":16,"text":"공부 성적이 나의 가치라고 생각한다.","subdomain":"학습 자기동일시 (Self-Identification with Study)","subdomainEn":"Self-Identification with Study","isReversed":false},{"id":17,"text":"시험 결과가 좋지 않으면 내 존재 자체가 부정되는 느낌이 든다.","subdomain":"학습 자기동일시 (Self-Identification with Study)","subdomainEn":"Self-Identification with Study","isReversed":false},{"id":18,"text":"공부를 잘해야만 사랑받을 수 있다고 느낀다.","subdomain":"학습 자기동일시 (Self-Identification with Study)","subdomainEn":"Self-Identification with Study","isReversed":false},{"id":19,"text":"성취가 없으면 스스로 무가치하게 느껴진다.","subdomain":"학습 자기동일시 (Self-Identification with Study)","subdomainEn":"Self-Identification with Study","isReversed":false},{"id":20,"text":"공부 외의 일에는 큰 의미를 느끼지 못한다.","subdomain":"학습 자기동일시 (Self-Identification with Study)","subdomainEn":"Self-Identification with Study","isReversed":false}]'::jsonb
)
