  question_count, duration_minutes,
  is_recommended, is_coming_soon,
  is_integrated, is_free, price_krw,
  subdomains, questions
) VALUES (
  'B-1',
  '만성피로 증후군 검사',
  'B',
  '만성피로 증후군',
  '지속적인 피로감과 회복 불능 상태의 정도를 측정합니다.',
  20,
  3,
  false,
  false,
  false,
  false,
  2900,
  '["신체적 소진 (Physical Exhaustion)","정서적 소진 (Emotional Burnout)","인지적 과부하 (Cognitive Overload)","회복력 부족 (Lack of Recovery)"]'::jsonb,
  '[{"id":1,"text":"잠을 자도 개운하지 않다.","subdomain":"신체적 소진 (Physical Exhaustion)","subdomainEn":"Physical Exhaustion","isReversed":false},{"id":2,"text":"공부 중 자주 몸이 무겁고 피로하다.","subdomain":"신체적 소진 (Physical Exhaustion)","subdomainEn":"Physical Exhaustion","isReversed":false},{"id":3,"text":"체력이 부족하여 금방 지치는 편이다.","subdomain":"신체적 소진 (Physical Exhaustion)","subdomainEn":"Physical Exhaustion","isReversed":false},{"id":4,"text":"자주 두통이나 근육통을 느낀다.","subdomain":"신체적 소진 (Physical Exhaustion)","subdomainEn":"Physical Exhaustion","isReversed":false},{"id":5,"text":"하루 종일 피곤함이 지속된다.","subdomain":"신체적 소진 (Physical Exhaustion)","subdomainEn":"Physical Exhaustion","isReversed":false},{"id":6,"text":"아무 이유없이 짜증이 나거나 예민하다.","subdomain":"정서적 소진 (Emotional Burnout)","subdomainEn":"Emotional Burnout","isReversed":false},{"id":7,"text":"예전보다 감정기복이 심해졌다.","subdomain":"정서적 소진 (Emotional Burnout)","subdomainEn":"Emotional Burnout","isReversed":false},{"id":8,"text":"공부에 대한 흥미나 의욕이 거의 없다.","subdomain":"정서적 소진 (Emotional Burnout)","subdomainEn":"Emotional Burnout","isReversed":false},{"id":9,"text":"작은 일에도 쉽게 낙담한다.","subdomain":"정서적 소진 (Emotional Burnout)","subdomainEn":"Emotional Burnout","isReversed":false},{"id":10,"text":"성취해도 기쁨보다는 허무함이 느껴진다.","subdomain":"정서적 소진 (Emotional Burnout)","subdomainEn":"Emotional Burnout","isReversed":false},{"id":11,"text":"집중하려해도 머리가 멍하거나 잘 안잡힌다.","subdomain":"인지적 과부하 (Cognitive Overload)","subdomainEn":"Cognitive Overload","isReversed":false},{"id":12,"text":"공부 내용이 쉽게 머릿속에 들어오지 않는다.","subdomain":"인지적 과부하 (Cognitive Overload)","subdomainEn":"Cognitive Overload","isReversed":false},{"id":13,"text":"생각이 너무 많아 정리가 되지 않는다.","subdomain":"인지적 과부하 (Cognitive Overload)","subdomainEn":"Cognitive Overload","isReversed":false},{"id":14,"text":"공부 중 사소한 일에 자꾸 신경이 분산된다.","subdomain":"인지적 과부하 (Cognitive Overload)","subdomainEn":"Cognitive Overload","isReversed":false},{"id":15,"text":"기억력이 예전보다 떨어진 것 같다.","subdomain":"인지적 과부하 (Cognitive Overload)","subdomainEn":"Cognitive Overload","isReversed":false},{"id":16,"text":"쉬어도 피로가 쉽게 풀리지 않는다.","subdomain":"회복력 부족 (Lack of Recovery)","subdomainEn":"Lack of Recovery","isReversed":false},{"id":17,"text":"잠시 휴식을 가져도 금세 다시 피로해진다.","subdomain":"회복력 부족 (Lack of Recovery)","subdomainEn":"Lack of Recovery","isReversed":false},{"id":18,"text":"스트레스를 푸는 방법을 몰라서 계속 쌓인다.","subdomain":"회복력 부족 (Lack of Recovery)","subdomainEn":"Lack of Recovery","isReversed":false},{"id":19,"text":"공부 외에는 아무것도 하고 싶지 않다.","subdomain":"회복력 부족 (Lack of Recovery)","subdomainEn":"Lack of Recovery","isReversed":false},{"id":20,"text":"내 몸과 마음이 늘 ''방전된 상태''처럼 느껴진다.","subdomain":"회복력 부족 (Lack of Recovery)","subdomainEn":"Lack of Recovery","isReversed":false}]'::jsonb
)
