INSERT INTO public.tests (
  id, name, category, related_syndrome, description,
  question_count, duration_minutes,
  is_recommended, is_coming_soon,
  is_integrated, is_free, price_krw,
  subdomains, questions
) VALUES (
  'B-2',
  '분노조절 곤란 증후군 검사',
  'B',
  '분노조절 곤란 증후군',
  '학업 스트레스로 인한 분노 표현과 조절 곤란 수준을 측정합니다.',
  20,
  3,
  false,
  false,
  false,
  false,
  2900,
  '["충동적 반응성 (Impulsive Reactivity)","억압-분노 축적 (Suppressed-Angry Accumulation)","외적 분노 귀인 (Externalized Anger Attribution)","자기향 분노 (Self-Directed Anger)"]'::jsonb,
  '[{"id":1,"text":"화가 나면 참지 못하고 바로 반응하는 편이다.","subdomain":"충동적 반응성 (Impulsive Reactivity)","subdomainEn":"Impulsive Reactivity","isReversed":false},{"id":2,"text":"작은 일에도 짜증이 쉽게 올라온다.","subdomain":"충동적 반응성 (Impulsive Reactivity)","subdomainEn":"Impulsive Reactivity","isReversed":false},{"id":3,"text":"공부 방해를 받으면 바로 화가 난다.","subdomain":"충동적 반응성 (Impulsive Reactivity)","subdomainEn":"Impulsive Reactivity","isReversed":false},{"id":4,"text":"분노를 느낄 때 감정을 통제하기 어렵다.","subdomain":"충동적 반응성 (Impulsive Reactivity)","subdomainEn":"Impulsive Reactivity","isReversed":false},{"id":5,"text":"감정이 올라오면 후회할 말을 하기도 한다.","subdomain":"충동적 반응성 (Impulsive Reactivity)","subdomainEn":"Impulsive Reactivity","isReversed":false},{"id":6,"text":"화를 잘 내지 않지만, 쌓이면 폭발하는 편이다.","subdomain":"억압-분노 축적 (Suppressed-Angry Accumulation)","subdomainEn":"Suppressed-Angry Accumulation","isReversed":false},{"id":7,"text":"속으로는 화가 나지만 겉으로 표현하지 못한다.","subdomain":"억압-분노 축적 (Suppressed-Angry Accumulation)","subdomainEn":"Suppressed-Angry Accumulation","isReversed":false},{"id":8,"text":"참는 일이 많아질수록 몸이 더 피곤해진다.","subdomain":"억압-분노 축적 (Suppressed-Angry Accumulation)","subdomainEn":"Suppressed-Angry Accumulation","isReversed":false},{"id":9,"text":"분노를 억누르다 갑자기 폭발할 때가 있다.","subdomain":"억압-분노 축적 (Suppressed-Angry Accumulation)","subdomainEn":"Suppressed-Angry Accumulation","isReversed":false},{"id":10,"text":"감정을 표현하면 후회할 것 같아서 참는다.","subdomain":"억압-분노 축적 (Suppressed-Angry Accumulation)","subdomainEn":"Suppressed-Angry Accumulation","isReversed":false},{"id":11,"text":"내 화는 주로 다른 사람 때문이라고 느껴진다.","subdomain":"외적 분노 귀인 (Externalized Anger Attribution)","subdomainEn":"Externalized Anger Attribution","isReversed":false},{"id":12,"text":"공부가 안 될 때 주변환경이나 사람 탓을 하게 된다.","subdomain":"외적 분노 귀인 (Externalized Anger Attribution)","subdomainEn":"Externalized Anger Attribution","isReversed":false},{"id":13,"text":"누군가 내 계획을 방해하면 쉽게 짜증이 난다.","subdomain":"외적 분노 귀인 (Externalized Anger Attribution)","subdomainEn":"Externalized Anger Attribution","isReversed":false},{"id":14,"text":"내가 힘든 이유를 부모님이나 선생님 탓으로 돌릴 때가 있다.","subdomain":"외적 분노 귀인 (Externalized Anger Attribution)","subdomainEn":"Externalized Anger Attribution","isReversed":false},{"id":15,"text":"''왜 나만 이런 일이 일어날까?''라는 생각이 든다.","subdomain":"외적 분노 귀인 (Externalized Anger Attribution)","subdomainEn":"Externalized Anger Attribution","isReversed":false},{"id":16,"text":"화가 나면 결국 ''내가 못나서 그렇다''는 생각이 든다.","subdomain":"자기향 분노 (Self-Directed Anger)","subdomainEn":"Self-Directed Anger","isReversed":false},{"id":17,"text":"실패하면 남보다 자신을 먼저 탓한다.","subdomain":"자기향 분노 (Self-Directed Anger)","subdomainEn":"Self-Directed Anger","isReversed":false},{"id":18,"text":"감정을 폭발한 후, 심한 죄책감을 느낀다.","subdomain":"자기향 분노 (Self-Directed Anger)","subdomainEn":"Self-Directed Anger","isReversed":false},{"id":19,"text":"분노가 쌓이면 스스로에게 화풀이를 하는 편이다.","subdomain":"자기향 분노 (Self-Directed Anger)","subdomainEn":"Self-Directed Anger","isReversed":false},{"id":20,"text":"화를 내면 이런 내가 싫다는 생각이 든다.","subdomain":"자기향 분노 (Self-Directed Anger)","subdomainEn":"Self-Directed Anger","isReversed":false}]'::jsonb
)
