) VALUES (
  'B-3',
  '소진 증후군 검사',
  'B',
  '소진 증후군',
  '에너지 고갈과 정서적·신체적 소진 수준을 측정합니다.',
  20,
  3,
  false,
  false,
  false,
  false,
  2900,
  '["정서적 고갈 (Emotional Exhaustion)","비인격화·무력감 (Depersonalization & Helplessness)","성취감 저하 (Reduced Accomplishment)","회복탄력성 저하 (Resilience Decline)"]'::jsonb,
  '[{"id":1,"text":"최근 감정이 쉽게 바닥나고 아무 의욕이 없다.","subdomain":"정서적 고갈 (Emotional Exhaustion)","subdomainEn":"Emotional Exhaustion","isReversed":false},{"id":2,"text":"사람을 대하거나 대화하는 것이 부담스럽다.","subdomain":"정서적 고갈 (Emotional Exhaustion)","subdomainEn":"Emotional Exhaustion","isReversed":false},{"id":3,"text":"아무 일도 하지 않아도 피로감이 느껴진다.","subdomain":"정서적 고갈 (Emotional Exhaustion)","subdomainEn":"Emotional Exhaustion","isReversed":false},{"id":4,"text":"해야 할 일을 떠올리면 숨이 막히거나 지친다.","subdomain":"정서적 고갈 (Emotional Exhaustion)","subdomainEn":"Emotional Exhaustion","isReversed":false},{"id":5,"text":"예전에 즐겁던 일도 이제는 무기력하게 느껴진다.","subdomain":"정서적 고갈 (Emotional Exhaustion)","subdomainEn":"Emotional Exhaustion","isReversed":false},{"id":6,"text":"''해봤자 달라지지 않는다''는 생각이 자주 든다.","subdomain":"비인격화·무력감 (Depersonalization & Helplessness)","subdomainEn":"Depersonalization & Helplessness","isReversed":false},{"id":7,"text":"일이나 사람에 대해 점점 냉소적으로 변하고 있다.","subdomain":"비인격화·무력감 (Depersonalization & Helplessness)","subdomainEn":"Depersonalization & Helplessness","isReversed":false},{"id":8,"text":"책임감보다는 회피하고 싶은 마음이 더 크다.","subdomain":"비인격화·무력감 (Depersonalization & Helplessness)","subdomainEn":"Depersonalization & Helplessness","isReversed":false},{"id":9,"text":"나 자신이 무의미하게 느껴질 때가 있다.","subdomain":"비인격화·무력감 (Depersonalization & Helplessness)","subdomainEn":"Depersonalization & Helplessness","isReversed":false},{"id":10,"text":"''다 포기해버리고 싶다''는 생각이 든 적이 있다.","subdomain":"비인격화·무력감 (Depersonalization & Helplessness)","subdomainEn":"Depersonalization & Helplessness","isReversed":false},{"id":11,"text":"최근 나의 능력에 대한 자신감이 떨어지고 있다.","subdomain":"성취감 저하 (Reduced Accomplishment)","subdomainEn":"Reduced Accomplishment","isReversed":false},{"id":12,"text":"집중이 잘 안되고 일의 성과가 줄어든 느낌이다.","subdomain":"성취감 저하 (Reduced Accomplishment)","subdomainEn":"Reduced Accomplishment","isReversed":false},{"id":13,"text":"내 역할이 별로 중요하지 않다고 느껴진다.","subdomain":"성취감 저하 (Reduced Accomplishment)","subdomainEn":"Reduced Accomplishment","isReversed":false},{"id":14,"text":"열심히 해도 성취감이 없다.","subdomain":"성취감 저하 (Reduced Accomplishment)","subdomainEn":"Reduced Accomplishment","isReversed":false},{"id":15,"text":"내가 하는 일이 의미 없다고 느껴진다.","subdomain":"성취감 저하 (Reduced Accomplishment)","subdomainEn":"Reduced Accomplishment","isReversed":false},{"id":16,"text":"힘든 일이 있어도 다시 일어서기 힘들다.","subdomain":"회복탄력성 저하 (Resilience Decline)","subdomainEn":"Resilience Decline","isReversed":false},{"id":17,"text":"스스로를 위로하거나 돌보는 방법을 잘 모르겠다.","subdomain":"회복탄력성 저하 (Resilience Decline)","subdomainEn":"Resilience Decline","isReversed":false},{"id":18,"text":"스트레스를 해소하기보다 쌓아두는 편이다.","subdomain":"회복탄력성 저하 (Resilience Decline)","subdomainEn":"Resilience Decline","isReversed":false},{"id":19,"text":"쉬어도 마음이 편해지지 않는다.","subdomain":"회복탄력성 저하 (Resilience Decline)","subdomainEn":"Resilience Decline","isReversed":false},{"id":20,"text":"나를 다시 일으킬 힘이 거의 남아있지 않다고 느낀다.","subdomain":"회복탄력성 저하 (Resilience Decline)","subdomainEn":"Resilience Decline","isReversed":false}]'::jsonb
)
