INSERT INTO public.tests (
  id, name, category, related_syndrome, description,
  question_count, duration_minutes,
  is_recommended, is_coming_soon,
  is_integrated, is_free, price_krw,
  subdomains, questions
) VALUES (
  'B-4',
  '예상불안 증후군 검사',
  'B',
  '예상불안 증후군',
  '미래에 대한 과도한 걱정과 예기 불안 수준을 측정합니다.',
  20,
  3,
  false,
  false,
  false,
  false,
  2900,
  '["예상 통제 불안 (Anticipated Control Distress)","결과 예측 과잉형 (Outcome Prediction Overtype)","평가 민감형 (Sensitive Type for Evaluation)","자기조절 결핍형 (Self-Regulating Deficiency Type)"]'::jsonb,
  '[{"id":1,"text":"시험 전 계획이 조금만 어긋나도 불안해진다.","subdomain":"예상 통제 불안 (Anticipated Control Distress)","subdomainEn":"Anticipated Control Distress","isReversed":false},{"id":2,"text":"공부 루틴이 망가지면 하루가 망했다고 느낀다.","subdomain":"예상 통제 불안 (Anticipated Control Distress)","subdomainEn":"Anticipated Control Distress","isReversed":false},{"id":3,"text":"시험 직전에 모든 상황을 내 뜻대로 통제하고 싶다.","subdomain":"예상 통제 불안 (Anticipated Control Distress)","subdomainEn":"Anticipated Control Distress","isReversed":false},{"id":4,"text":"예상치 못한 일정이나 변수에 스트레스를 크게 받는다.","subdomain":"예상 통제 불안 (Anticipated Control Distress)","subdomainEn":"Anticipated Control Distress","isReversed":false},{"id":5,"text":"컨디션이 완벽하지 않으면 불안해서 공부가 잘 안된다.","subdomain":"예상 통제 불안 (Anticipated Control Distress)","subdomainEn":"Anticipated Control Distress","isReversed":false},{"id":6,"text":"시험을 보기 전부터 결과를 여러 번 상상한다.","subdomain":"결과 예측 과잉형 (Outcome Prediction Overtype)","subdomainEn":"Outcome Prediction Overtype","isReversed":false},{"id":7,"text":"\"망하면 어떡하지?\"라는 생각이 자주 떠오른다.","subdomain":"결과 예측 과잉형 (Outcome Prediction Overtype)","subdomainEn":"Outcome Prediction Overtype","isReversed":false},{"id":8,"text":"시험이 끝나기도 전에 성적이 떨어졌다고 확신한다.","subdomain":"결과 예측 과잉형 (Outcome Prediction Overtype)","subdomainEn":"Outcome Prediction Overtype","isReversed":false},{"id":9,"text":"좋은 결과를 기대하기보다 실패할까 봐 두렵다.","subdomain":"결과 예측 과잉형 (Outcome Prediction Overtype)","subdomainEn":"Outcome Prediction Overtype","isReversed":false},{"id":10,"text":"결과가 나올 때까지 다른 일에 집중이 어렵다.","subdomain":"결과 예측 과잉형 (Outcome Prediction Overtype)","subdomainEn":"Outcome Prediction Overtype","isReversed":false},{"id":11,"text":"부모님이나 선생님이 실망할까 봐 불안하다.","subdomain":"평가 민감형 (Sensitive Type for Evaluation)","subdomainEn":"Sensitive Type for Evaluation","isReversed":false},{"id":12,"text":"친구들이 나보다 잘하면 자존심이 상한다.","subdomain":"평가 민감형 (Sensitive Type for Evaluation)","subdomainEn":"Sensitive Type for Evaluation","isReversed":false},{"id":13,"text":"주변 사람들의 기대를 충족하지 못할까 봐 부담스럽다.","subdomain":"평가 민감형 (Sensitive Type for Evaluation)","subdomainEn":"Sensitive Type for Evaluation","isReversed":false},{"id":14,"text":"시험이 끝난 후 다른 사람의 반응이 가장 걱정된다.","subdomain":"평가 민감형 (Sensitive Type for Evaluation)","subdomainEn":"Sensitive Type for Evaluation","isReversed":false},{"id":15,"text":"''결과로 평가받는다''라는 생각이 자주 든다.","subdomain":"평가 민감형 (Sensitive Type for Evaluation)","subdomainEn":"Sensitive Type for Evaluation","isReversed":false},{"id":16,"text":"불안할 때 공부 대신 딴짓을 하게 된다.","subdomain":"자기조절 결핍형 (Self-Regulating Deficiency Type)","subdomainEn":"Self-Regulating Deficiency Type","isReversed":false},{"id":17,"text":"불안을 느껴도 어떻게 다뤄야 할지 모르겠다.","subdomain":"자기조절 결핍형 (Self-Regulating Deficiency Type)","subdomainEn":"Self-Regulating Deficiency Type","isReversed":false},{"id":18,"text":"시험 전날에는 집중이 잘 안되고 쉽게 산만해진다.","subdomain":"자기조절 결핍형 (Self-Regulating Deficiency Type)","subdomainEn":"Self-Regulating Deficiency Type","isReversed":false},{"id":19,"text":"불안을 느낄 때 스스로 다독이기보다 자책한다.","subdomain":"자기조절 결핍형 (Self-Regulating Deficiency Type)","subdomainEn":"Self-Regulating Deficiency Type","isReversed":false},{"id":20,"text":"긴장 상황에서도 마음을 안정시키는 방법이 없다.","subdomain":"자기조절 결핍형 (Self-Regulating Deficiency Type)","subdomainEn":"Self-Regulating Deficiency Type","isReversed":false}]'::jsonb
)
