INSERT INTO public.tests (
  id, name, category, related_syndrome, description,
  question_count, duration_minutes,
  is_recommended, is_coming_soon,
  is_integrated, is_free, price_krw,
  subdomains, questions
) VALUES (
  'B-5',
  '자기정체감 혼란 증후군 검사',
  'B',
  '자기정체감 혼란 증후군',
  '자기 정체성과 진로에 대한 혼란 및 불확실감을 측정합니다.',
  20,
  3,
  false,
  false,
  false,
  false,
  2900,
  '["목표 모호성 (Goal Ambiguity)","타인 의존적 정체성 (Other-Dependent Identity)","자기인식 부족 (Lack of Self-Awareness)","실존적 공허감 (Existential Emptiness)"]'::jsonb,
  '[{"id":1,"text":"내가 왜 공부해야 하는지 명확하지 않다.","subdomain":"목표 모호성 (Goal Ambiguity)","subdomainEn":"Goal Ambiguity","isReversed":false},{"id":2,"text":"공부의 최종 목표가 자주 바뀐다.","subdomain":"목표 모호성 (Goal Ambiguity)","subdomainEn":"Goal Ambiguity","isReversed":false},{"id":3,"text":"성적이 좋아도 왜 기쁜지 모르겠다.","subdomain":"목표 모호성 (Goal Ambiguity)","subdomainEn":"Goal Ambiguity","isReversed":false},{"id":4,"text":"공부를 하면서 방향성을 잃은 느낌이 든다.","subdomain":"목표 모호성 (Goal Ambiguity)","subdomainEn":"Goal Ambiguity","isReversed":false},{"id":5,"text":"목표를 세워도 금세 의미를 잃는다.","subdomain":"목표 모호성 (Goal Ambiguity)","subdomainEn":"Goal Ambiguity","isReversed":false},{"id":6,"text":"부모님이나 선생님이 원하는 길을 따라가야 한다고 느낀다.","subdomain":"타인 의존적 정체성 (Other-Dependent Identity)","subdomainEn":"Other-Dependent Identity","isReversed":false},{"id":7,"text":"다른 사람의 시선에 따라 내 진로를 바꾼 적이 있다.","subdomain":"타인 의존적 정체성 (Other-Dependent Identity)","subdomainEn":"Other-Dependent Identity","isReversed":false},{"id":8,"text":"타인의 칭찬이나 인정을 받지 못하면 자신감이 떨어진다.","subdomain":"타인 의존적 정체성 (Other-Dependent Identity)","subdomainEn":"Other-Dependent Identity","isReversed":false},{"id":9,"text":"남이 정한 기준을 만족시키지 못하면 불안하다.","subdomain":"타인 의존적 정체성 (Other-Dependent Identity)","subdomainEn":"Other-Dependent Identity","isReversed":false},{"id":10,"text":"''내가 원하는 길''보다 ''남이 인정하는 길''을 더 중요하게 생각한다.","subdomain":"타인 의존적 정체성 (Other-Dependent Identity)","subdomainEn":"Other-Dependent Identity","isReversed":false},{"id":11,"text":"내가 진짜 좋아하는 과목이나 일이 무엇인지 잘 모르겠다.","subdomain":"자기인식 부족 (Lack of Self-Awareness)","subdomainEn":"Lack of Self-Awareness","isReversed":false},{"id":12,"text":"나의 감정이나 장점을 떠올리기 어렵다.","subdomain":"자기인식 부족 (Lack of Self-Awareness)","subdomainEn":"Lack of Self-Awareness","isReversed":false},{"id":13,"text":"공부 외의 나 자신에 대해서는 생각해 본 적이 거의 없다.","subdomain":"자기인식 부족 (Lack of Self-Awareness)","subdomainEn":"Lack of Self-Awareness","isReversed":false},{"id":14,"text":"내 감정이나 생각을 스스로 설명하기 어렵다.","subdomain":"자기인식 부족 (Lack of Self-Awareness)","subdomainEn":"Lack of Self-Awareness","isReversed":false},{"id":15,"text":"목표는 있지만, 그것이 나와 어울리는지 모르겠다.","subdomain":"자기인식 부족 (Lack of Self-Awareness)","subdomainEn":"Lack of Self-Awareness","isReversed":false},{"id":16,"text":"공부를 열심히해도 마음이 공허하다.","subdomain":"실존적 공허감 (Existential Emptiness)","subdomainEn":"Existential Emptiness","isReversed":false},{"id":17,"text":"시험이 끝나면 갑자기 방향을 잃을 것 같다.","subdomain":"실존적 공허감 (Existential Emptiness)","subdomainEn":"Existential Emptiness","isReversed":false},{"id":18,"text":"공부 외에는 내 인생에 의미가 없는 것 같다.","subdomain":"실존적 공허감 (Existential Emptiness)","subdomainEn":"Existential Emptiness","isReversed":false},{"id":19,"text":"미래를 상상할 때 두려움이나 허무함이 먼저 든다.","subdomain":"실존적 공허감 (Existential Emptiness)","subdomainEn":"Existential Emptiness","isReversed":false},{"id":20,"text":"성취를 해도 ''이게 정말 내가 원하던 걸까?''라는 의문이 든다.","subdomain":"실존적 공허감 (Existential Emptiness)","subdomainEn":"Existential Emptiness","isReversed":false}]'::jsonb
)
