INSERT INTO public.tests (
  id, name, category, related_syndrome, description,
  question_count, duration_minutes,
  is_recommended, is_coming_soon,
  is_integrated, is_free, price_krw,
  subdomains, questions
) VALUES (
  'B-6',
  '학습회피 증후군 검사',
  'B',
  '학습회피 증후군',
  '학습 자체를 회피하거나 시작하지 못하는 경향을 측정합니다.',
  20,
  3,
  false,
  false,
  false,
  false,
  2900,
  '["실패 공포 회피 (Fear of Failure Avoidance)","자기비판적 철수 (Self-Critical Withdrawal)","완벽주의적 미루기 (Perfectionistic Procrastination)","학습된 무기력 (Learned Helplessness)"]'::jsonb,
  '[{"id":1,"text":"공부를 시작하려고 하면 ''이번에도 안 될 것 같다''는 생각이 든다.","subdomain":"실패 공포 회피 (Fear of Failure Avoidance)","subdomainEn":"Fear of Failure Avoidance","isReversed":false},{"id":2,"text":"실패할까봐 아예 시작하지 않을 때가 있다.","subdomain":"실패 공포 회피 (Fear of Failure Avoidance)","subdomainEn":"Fear of Failure Avoidance","isReversed":false},{"id":3,"text":"목표를 세워도 실망할까 실행이 어렵다.","subdomain":"실패 공포 회피 (Fear of Failure Avoidance)","subdomainEn":"Fear of Failure Avoidance","isReversed":false},{"id":4,"text":"시험이 다가올수록 오히려 공부를 피하고 싶어진다.","subdomain":"실패 공포 회피 (Fear of Failure Avoidance)","subdomainEn":"Fear of Failure Avoidance","isReversed":false},{"id":5,"text":"공부를 미루면 불안하지만, 시작하면 더 불안하다.","subdomain":"실패 공포 회피 (Fear of Failure Avoidance)","subdomainEn":"Fear of Failure Avoidance","isReversed":false},{"id":6,"text":"공부를 시작하면 스스로에게 화가 나거나 실망한다.","subdomain":"자기비판적 철수 (Self-Critical Withdrawal)","subdomainEn":"Self-Critical Withdrawal","isReversed":false},{"id":7,"text":"자신을 자주 비난해서 공부가 더 하기 싫어진다.","subdomain":"자기비판적 철수 (Self-Critical Withdrawal)","subdomainEn":"Self-Critical Withdrawal","isReversed":false},{"id":8,"text":"실패하면 ''역시 난 안돼''라는 생각이 들어서 시도 자체를 피한다.","subdomain":"자기비판적 철수 (Self-Critical Withdrawal)","subdomainEn":"Self-Critical Withdrawal","isReversed":false},{"id":9,"text":"잘못될까 봐 아예 도전하지 않는 편이다.","subdomain":"자기비판적 철수 (Self-Critical Withdrawal)","subdomainEn":"Self-Critical Withdrawal","isReversed":false},{"id":10,"text":"공부를 피하면서 죄책감을 느끼지만, 동시에 안심하기도 한다.","subdomain":"자기비판적 철수 (Self-Critical Withdrawal)","subdomainEn":"Self-Critical Withdrawal","isReversed":false},{"id":11,"text":"완벽한 계획이 세워지지 않으면 공부를 시작하지 않는다.","subdomain":"완벽주의적 미루기 (Perfectionistic Procrastination)","subdomainEn":"Perfectionistic Procrastination","isReversed":false},{"id":12,"text":"''이번엔 완벽히 해야지''라는 생각 때문에 부담이 크다.","subdomain":"완벽주의적 미루기 (Perfectionistic Procrastination)","subdomainEn":"Perfectionistic Procrastination","isReversed":false},{"id":13,"text":"계획이 조금만 틀어져도 공부 의욕이 사라진다.","subdomain":"완벽주의적 미루기 (Perfectionistic Procrastination)","subdomainEn":"Perfectionistic Procrastination","isReversed":false},{"id":14,"text":"완벽히 준비되지 않으면 ''괜히 해봤자''라는 생각이 든다.","subdomain":"완벽주의적 미루기 (Perfectionistic Procrastination)","subdomainEn":"Perfectionistic Procrastination","isReversed":false},{"id":15,"text":"공부를 시작하기 전 준비과정(정리, 계획)에만 지나치게 집중한다.","subdomain":"완벽주의적 미루기 (Perfectionistic Procrastination)","subdomainEn":"Perfectionistic Procrastination","isReversed":false},{"id":16,"text":"아무리 노력해도 성적이 오르지 않는다는 생각이 든다.","subdomain":"학습된 무기력 (Learned Helplessness)","subdomainEn":"Learned Helplessness","isReversed":false},{"id":17,"text":"공부를 해도 의미가 없다고 느낀다.","subdomain":"학습된 무기력 (Learned Helplessness)","subdomainEn":"Learned Helplessness","isReversed":false},{"id":18,"text":"의욕이 생겨도 금세 사라진다.","subdomain":"학습된 무기력 (Learned Helplessness)","subdomainEn":"Learned Helplessness","isReversed":false},{"id":19,"text":"다른 사람은 해내는데, 나는 안 될 거라고 느낀다.","subdomain":"학습된 무기력 (Learned Helplessness)","subdomainEn":"Learned Helplessness","isReversed":false},{"id":20,"text":"공부할 에너지가 남아 있지 않은 느낌이다.","subdomain":"학습된 무기력 (Learned Helplessness)","subdomainEn":"Learned Helplessness","isReversed":false}]'::jsonb
)
