  '[{"id":1,"text":"사람들 앞에 서면 내 말투나 표정이 신경 쓰인다.","subdomain":"수행 평가 불안","subdomainEn":"Performance Evaluation Anxiety","isReversed":false},{"id":2,"text":"발표 중 누가 나를 쳐다보면 불안이 커진다.","subdomain":"수행 평가 불안","subdomainEn":"Performance Evaluation Anxiety","isReversed":false},{"id":3,"text":"실수하면 다른 사람이 나를 비웃을까 걱정된다.","subdomain":"수행 평가 불안","subdomainEn":"Performance Evaluation Anxiety","isReversed":false},{"id":4,"text":"면접관의 표정 하나에도 영향을 많이 받는다.","subdomain":"수행 평가 불안","subdomainEn":"Performance Evaluation Anxiety","isReversed":false},{"id":5,"text":"타인의 시선이 느껴지면 생각이 잘 안 난다.","subdomain":"수행 평가 불안","subdomainEn":"Performance Evaluation Anxiety","isReversed":false},{"id":6,"text":"무대에 오르면 손이나 다리가 떨린다.","subdomain":"생리적 반응 불안","subdomainEn":"Physiological Response Anxiety","isReversed":false},{"id":7,"text":"발표 전에 심장이 빠르게 뛰는 걸 느낀다.","subdomain":"생리적 반응 불안","subdomainEn":"Physiological Response Anxiety","isReversed":false},{"id":8,"text":"긴장하면 목이 메이거나 말이 꼬인다.","subdomain":"생리적 반응 불안","subdomainEn":"Physiological Response Anxiety","isReversed":false},{"id":9,"text":"발표 중 호흡이 짧아지고 머리가 하얘진다.","subdomain":"생리적 반응 불안","subdomainEn":"Physiological Response Anxiety","isReversed":false},{"id":10,"text":"발표 후에도 긴장감이 오래 남는다.","subdomain":"생리적 반응 불안","subdomainEn":"Physiological Response Anxiety","isReversed":false},{"id":11,"text":"발표가 끝나면 ''내가 너무 못했어''라고 자책한다.","subdomain":"자기비판 불안","subdomainEn":"Self-Critical Anxiety","isReversed":false},{"id":12,"text":"실수 한번으로 전체를 망쳤다고 느낀다.","subdomain":"자기비판 불안","subdomainEn":"Self-Critical Anxiety","isReversed":false},{"id":13,"text":"발표 후 다른 사람보다 부족했다고 느낀다.","subdomain":"자기비판 불안","subdomainEn":"Self-Critical Anxiety","isReversed":false},{"id":14,"text":"발표 전부터 \"이번엔 또 틀릴거야\"라는 생각이 든다.","subdomain":"자기비판 불안","subdomainEn":"Self-Critical Anxiety","isReversed":false},{"id":15,"text":"남보다 부족한 자신을 자주 비난한다.","subdomain":"자기비판 불안","subdomainEn":"Self-Critical Anxiety","isReversed":false},{"id":16,"text":"발표나 면접 전에 긴장을 풀기가 어렵다.","subdomain":"자기조절 결핍 불안","subdomainEn":"Self-Regulation Deficiency Anxiety","isReversed":false},{"id":17,"text":"불안이 커지면 머릿속이 복잡해져 말이 막힌다.","subdomain":"자기조절 결핍 불안","subdomainEn":"Self-Regulation Deficiency Anxiety","isReversed":false},{"id":18,"text":"사람들 앞에서 실수하면 그 이후로 집중이 안된다.","subdomain":"자기조절 결핍 불안","subdomainEn":"Self-Regulation Deficiency Anxiety","isReversed":false},{"id":19,"text":"발표 중 감정이 흔들려 목소리가 떨린다.","subdomain":"자기조절 결핍 불안","subdomainEn":"Self-Regulation Deficiency Anxiety","isReversed":false},{"id":20,"text":"무대에 설 때마다 자신을 통제하기 어렵다.","subdomain":"자기조절 결핍 불안","subdomainEn":"Self-Regulation Deficiency Anxiety","isReversed":false}]'::jsonb
