  '[{"id":1,"text":"친구의 성적이나 공부량을 들으면 나를 다시 평가하게 된다.","subdomain":"외부 비교 의존","subdomainEn":"External Comparison Dependence","isReversed":false},{"id":2,"text":"다른 사람의 성과가 내 기분에 큰 영향을 준다.","subdomain":"외부 비교 의존","subdomainEn":"External Comparison Dependence","isReversed":false},{"id":3,"text":"내 공부 실력은 항상 타인과 비교해서 판단된다.","subdomain":"외부 비교 의존","subdomainEn":"External Comparison Dependence","isReversed":false},{"id":4,"text":"주변 사람이 잘하면 나도 그만큼 해야 한다고 느낀다.","subdomain":"외부 비교 의존","subdomainEn":"External Comparison Dependence","isReversed":false},{"id":5,"text":"비교하지 않으면 불안하다.","subdomain":"외부 비교 의존","subdomainEn":"External Comparison Dependence","isReversed":false},{"id":6,"text":"누군가 나보다 잘하면 나의 가치가 떨어진다고 느낀다.","subdomain":"자존감 불안","subdomainEn":"Self-Esteem Anxiety","isReversed":false},{"id":7,"text":"시험 결과가 좋지 않으면 나라는 사람 자체가 부족하게 느껴진다.","subdomain":"자존감 불안","subdomainEn":"Self-Esteem Anxiety","isReversed":false},{"id":8,"text":"칭찬을 받아도 ''그래도 다른 애보다 못하잖아''라는 생각이 든다.","subdomain":"자존감 불안","subdomainEn":"Self-Esteem Anxiety","isReversed":false},{"id":9,"text":"나보다 뛰어난 사람을 보면 자신감이 급격히 낮아진다.","subdomain":"자존감 불안","subdomainEn":"Self-Esteem Anxiety","isReversed":false},{"id":10,"text":"성적이 오르지 않으면 스스로가 싫어진다.","subdomain":"자존감 불안","subdomainEn":"Self-Esteem Anxiety","isReversed":false},{"id":11,"text":"친구가 좋은 결과를 얻으면 속으로 불편한 감정이 든다.","subdomain":"질투·시기 반응","subdomainEn":"Envy-Jealousy Response","isReversed":false},{"id":12,"text":"남의 성공이 나의 실패처럼 느껴질때가 있다.","subdomain":"질투·시기 반응","subdomainEn":"Envy-Jealousy Response","isReversed":false},{"id":13,"text":"누군가의 칭찬을 들으면 괜히 기분이 나빠진다.","subdomain":"질투·시기 반응","subdomainEn":"Envy-Jealousy Response","isReversed":false},{"id":14,"text":"다른 사람의 공부 방식을 보면 ''저건 나랑 달라서 불공평해''라고 느낀다.","subdomain":"질투·시기 반응","subdomainEn":"Envy-Jealousy Response","isReversed":false},{"id":15,"text":"경쟁 상대가 잘되면 나도 더해야 한다는 압박을 느낀다.","subdomain":"질투·시기 반응","subdomainEn":"Envy-Jealousy Response","isReversed":false},{"id":16,"text":"다른 사람보다 뒤처지면 ''나는 가치 없는 사람''이라는 생각이 든다.","subdomain":"자기가치 왜곡","subdomainEn":"Self-Value Distortion","isReversed":false},{"id":17,"text":"비교 결과가 좋지 않으면 내 모든 노력이 무의미하게 느껴진다.","subdomain":"자기가치 왜곡","subdomainEn":"Self-Value Distortion","isReversed":false},{"id":18,"text":"남의 기준으로 내 성취를 판단한다.","subdomain":"자기가치 왜곡","subdomainEn":"Self-Value Distortion","isReversed":false},{"id":19,"text":"타인이 나를 어떻게 평가할지가 늘 신경 쓰인다.","subdomain":"자기가치 왜곡","subdomainEn":"Self-Value Distortion","isReversed":false},{"id":20,"text":"나의 장점보다 부족한 점에 더 주목한다.","subdomain":"자기가치 왜곡","subdomainEn":"Self-Value Distortion","isReversed":false}]'::jsonb
