  '정보과부하 증후군 검사',
  'C',
  '정보과부하 증후군',
  '과도한 정보 수집으로 인한 혼란과 의사결정 곤란을 측정합니다.',
  20,
  3,
  false,
  false,
  false,
  false,
  2900,
  '["결정 피로","비교 불안","주의 분산","인지 포화"]'::jsonb,
  '[{"id":1,"text":"공부할 때 어떤 교재나 인강을 선택할지 너무 고민된다.","subdomain":"결정 피로","subdomainEn":"Decision Fatigue","isReversed":false},{"id":2,"text":"공부 계획을 세우는 것만으로도 이미 피로감을 느낀다.","subdomain":"결정 피로","subdomainEn":"Decision Fatigue","isReversed":false},{"id":3,"text":"선택을 잘못하면 후회할까 봐 결정을 미룰 때가 많다.","subdomain":"결정 피로","subdomainEn":"Decision Fatigue","isReversed":false},{"id":4,"text":"새로운 정보가 많으면 오히려 집중이 어렵다.","subdomain":"결정 피로","subdomainEn":"Decision Fatigue","isReversed":false},{"id":5,"text":"''무엇을 해야 할지''보다 ''무엇을 하지 말아야 할지'' 고민이 많다.","subdomain":"결정 피로","subdomainEn":"Decision Fatigue","isReversed":false},{"id":6,"text":"다른 친구의 공부 방식이나 자료를 보면 불안해진다.","subdomain":"비교 불안","subdomainEn":"Comparative Anxiety","isReversed":false},{"id":7,"text":"SNS나 커뮤니티에서 다른 사람의 공부법을 자주 찾아본다.","subdomain":"비교 불안","subdomainEn":"Comparative Anxiety","isReversed":false},{"id":8,"text":"나보다 더 좋은 자료나 교재를 가진 사람을 보면 초조하다.","subdomain":"비교 불안","subdomainEn":"Comparative Anxiety","isReversed":false},{"id":9,"text":"타인의 성과를 보면 내 공부 방식이 틀린 것 같다는 생각이 든다.","subdomain":"비교 불안","subdomainEn":"Comparative Anxiety","isReversed":false},{"id":10,"text":"나보다 앞서가는 사람을 볼수록 자신감이 떨어진다.","subdomain":"비교 불안","subdomainEn":"Comparative Anxiety","isReversed":false},{"id":11,"text":"공부 중에도 휴대폰 알림이나 정보가 계속 신경 쓰인다.","subdomain":"주의 분산","subdomainEn":"Attention Fragmentation","isReversed":false},{"id":12,"text":"공부하다가 다른 생각이나 정보 검색으로 자주 새나간다.","subdomain":"주의 분산","subdomainEn":"Attention Fragmentation","isReversed":false},{"id":13,"text":"한 가지 과목에 집중하기보다 여러 과목을 동시에 하려다 흐름이 깨진다.","subdomain":"주의 분산","subdomainEn":"Attention Fragmentation","isReversed":false},{"id":14,"text":"새로운 공부법을 보면 지금 하던 걸 멈추고 바꾸고 싶어진다.","subdomain":"주의 분산","subdomainEn":"Attention Fragmentation","isReversed":false},{"id":15,"text":"학습 중 불필요한 정보가 자꾸 머릿속에 맴돈다.","subdomain":"주의 분산","subdomainEn":"Attention Fragmentation","isReversed":false},{"id":16,"text":"머리가 과열된 느낌이 들고 아무리 공부해도 정리가 안된다.","subdomain":"인지 포화","subdomainEn":"Cognitive Saturation","isReversed":false},{"id":17,"text":"공부 내용을 많이 넣을수록 오히려 헷갈린다.","subdomain":"인지 포화","subdomainEn":"Cognitive Saturation","isReversed":false},{"id":18,"text":"하루 공부 후에는 머리가 ''비워지지 않는'' 느낌이 든다.","subdomain":"인지 포화","subdomainEn":"Cognitive Saturation","isReversed":false},{"id":19,"text":"너무 많은 정보로 인해 정작 중요한 내용을 놓칠때가 많다.","subdomain":"인지 포화","subdomainEn":"Cognitive Saturation","isReversed":false},{"id":20,"text":"생각이 많고 복잡해지면서 결단력이 떨어진다.","subdomain":"인지 포화","subdomainEn":"Cognitive Saturation","isReversed":false}]'::jsonb
)
