  '[{"id":1,"text":"공부 중 어깨나 목이 자주 뻐근하거나 걸린다.","subdomain":"긴장 스트레스 반응","subdomainEn":"Tension Stress Response","isReversed":false},{"id":2,"text":"긴장하면 머리가 조이듯 아프다.","subdomain":"긴장 스트레스 반응","subdomainEn":"Tension Stress Response","isReversed":false},{"id":3,"text":"스트레스를 받으면 두통이 심해진다.","subdomain":"긴장 스트레스 반응","subdomainEn":"Tension Stress Response","isReversed":false},{"id":4,"text":"시험 기간에는 두통이 자주 생긴다.","subdomain":"긴장 스트레스 반응","subdomainEn":"Tension Stress Response","isReversed":false},{"id":5,"text":"불안할 때 머리에 압박감이 느껴진다.","subdomain":"긴장 스트레스 반응","subdomainEn":"Tension Stress Response","isReversed":false},{"id":6,"text":"감정이 힘들면 몸이 먼저 반응하는 편이다.","subdomain":"신체화 자각","subdomainEn":"Somatization Awareness","isReversed":false},{"id":7,"text":"스트레스가 심할 때 머리 통증이나 어지럼이 동반된다.","subdomain":"신체화 자각","subdomainEn":"Somatization Awareness","isReversed":false},{"id":8,"text":"피로가 쌓이면 몸보다 머리가 먼저 아프다.","subdomain":"신체화 자각","subdomainEn":"Somatization Awareness","isReversed":false},{"id":9,"text":"마음이 불편하면 몸의 통증이 심해진다.","subdomain":"신체화 자각","subdomainEn":"Somatization Awareness","isReversed":false},{"id":10,"text":"정신적 긴장이 풀리면 두통이 완화되는 느낌이 든다.","subdomain":"신체화 자각","subdomainEn":"Somatization Awareness","isReversed":false},{"id":11,"text":"오랜 시간 집중하면 머리가 먹먹하거나 띵하다.","subdomain":"과집중 피로","subdomainEn":"Over-Concentration Fatigue","isReversed":false},{"id":12,"text":"문제를 오래 풀면 눈과 머리가 동시에 피로하다.","subdomain":"과집중 피로","subdomainEn":"Over-Concentration Fatigue","isReversed":false},{"id":13,"text":"공부 중 갑자기 머리가 멍해지는 느낌이 든다.","subdomain":"과집중 피로","subdomainEn":"Over-Concentration Fatigue","isReversed":false},{"id":14,"text":"화면(모니터, 스마트폰)을 오래 보면 두통이 생긴다.","subdomain":"과집중 피로","subdomainEn":"Over-Concentration Fatigue","isReversed":false},{"id":15,"text":"집중력이 떨어질 때 두통이 더 자주 나타난다.","subdomain":"과집중 피로","subdomainEn":"Over-Concentration Fatigue","isReversed":false},{"id":16,"text":"잠을 자도 두통이 완전히 사라지지 않는다.","subdomain":"회복 패턴 부족","subdomainEn":"Lack of Recovery Pattern","isReversed":false},{"id":17,"text":"두통이 자주 반복되어 일상이 방해된다.","subdomain":"회복 패턴 부족","subdomainEn":"Lack of Recovery Pattern","isReversed":false},{"id":18,"text":"쉬어도 머리가 개운하지 않다.","subdomain":"회복 패턴 부족","subdomainEn":"Lack of Recovery Pattern","isReversed":false},{"id":19,"text":"두통 때문에 공부 리듬이 자주 끊긴다.","subdomain":"회복 패턴 부족","subdomainEn":"Lack of Recovery Pattern","isReversed":false},{"id":20,"text":"몸과 마음이 모두 피로해서 두통이 만성화된 느낌이다.","subdomain":"회복 패턴 부족","subdomainEn":"Lack of Recovery Pattern","isReversed":false}]'::jsonb
