  '["성취 압박 불안","비교 기반 불안","자기비판 불안","자기조절 결핍 불안"]'::jsonb,
  '[{"id":1,"text":"목표를 이루지 못하면 큰 실패라고 느낀다.","subdomain":"성취 압박 불안","subdomainEn":"Achievement Pressure Anxiety","isReversed":false},{"id":2,"text":"''반드시 성공해야 한다''는 생각이 늘 머릿속에 있다.","subdomain":"성취 압박 불안","subdomainEn":"Achievement Pressure Anxiety","isReversed":false},{"id":3,"text":"높은 성취를 이루어야만 가치 있는 사람이라고 여긴다.","subdomain":"성취 압박 불안","subdomainEn":"Achievement Pressure Anxiety","isReversed":false},{"id":4,"text":"성적이 좋지 않으면 나의 노력이 의미가 없어 보인다.","subdomain":"성취 압박 불안","subdomainEn":"Achievement Pressure Anxiety","isReversed":false},{"id":5,"text":"주변의 기대를 충족하지 못할까 봐 늘 불안하다.","subdomain":"성취 압박 불안","subdomainEn":"Achievement Pressure Anxiety","isReversed":false},{"id":6,"text":"친구들이 나보다 공부를 잘하면 불안해진다.","subdomain":"비교 기반 불안","subdomainEn":"Comparison-Based Anxiety","isReversed":false},{"id":7,"text":"다른 사람의 성취를 보면 조급해진다.","subdomain":"비교 기반 불안","subdomainEn":"Comparison-Based Anxiety","isReversed":false},{"id":8,"text":"나보다 앞서가는 친구를 보면 열등감이 든다.","subdomain":"비교 기반 불안","subdomainEn":"Comparison-Based Anxiety","isReversed":false},{"id":9,"text":"SNS나 커뮤니티의 다른 수험생을 보며 불안감을 느낀다.","subdomain":"비교 기반 불안","subdomainEn":"Comparison-Based Anxiety","isReversed":false},{"id":10,"text":"늘 나의 위치를 주변과 비교하게 된다.","subdomain":"비교 기반 불안","subdomainEn":"Comparison-Based Anxiety","isReversed":false},{"id":11,"text":"목표를 이루지 못하면 스스로를 심하게 질책한다.","subdomain":"자기비판 불안","subdomainEn":"Self-Critical Anxiety","isReversed":false},{"id":12,"text":"실패했을 때 \"나는 안 되는 사람이야\"라고 느낀다.","subdomain":"자기비판 불안","subdomainEn":"Self-Critical Anxiety","isReversed":false},{"id":13,"text":"공부가 안될 때마다 죄책감이 든다.","subdomain":"자기비판 불안","subdomainEn":"Self-Critical Anxiety","isReversed":false},{"id":14,"text":"노력해도 성과가 없으면 내 탓이라고 생각한다.","subdomain":"자기비판 불안","subdomainEn":"Self-Critical Anxiety","isReversed":false},{"id":15,"text":"다른 사람은 하는데 나만 부족하다고 생각이 든다.","subdomain":"자기비판 불안","subdomainEn":"Self-Critical Anxiety","isReversed":false},{"id":16,"text":"불안이 쌓이면 집중력이 급격히 떨어진다.","subdomain":"자기조절 결핍 불안","subdomainEn":"Self-Regulation Deficiency Anxiety","isReversed":false},{"id":17,"text":"공부 중 불안하면 딴짓을 하거나 회피하게 된다.","subdomain":"자기조절 결핍 불안","subdomainEn":"Self-Regulation Deficiency Anxiety","isReversed":false},{"id":18,"text":"성취 압박이 커질수록 무기력해진다.","subdomain":"자기조절 결핍 불안","subdomainEn":"Self-Regulation Deficiency Anxiety","isReversed":false},{"id":19,"text":"불안할 때 감정을 조절하기 어렵다.","subdomain":"자기조절 결핍 불안","subdomainEn":"Self-Regulation Deficiency Anxiety","isReversed":false},{"id":20,"text":"실패 후 회복이 잘 되지 않는다.","subdomain":"자기조절 결핍 불안","subdomainEn":"Self-Regulation Deficiency Anxiety","isReversed":false}]'::jsonb
)
