  '[{"id":1,"text":"시험이 다가오면 속이 자주 더부룩하다.","subdomain":"긴장성 소화불량","subdomainEn":"Tension-Induced Dyspepsia","isReversed":false},{"id":2,"text":"긴장하면 식욕이 떨어진다.","subdomain":"긴장성 소화불량","subdomainEn":"Tension-Induced Dyspepsia","isReversed":false},{"id":3,"text":"불안할 때 위가 쓰리거나 배가 아프다.","subdomain":"긴장성 소화불량","subdomainEn":"Tension-Induced Dyspepsia","isReversed":false},{"id":4,"text":"스트레스를 받으면 소화가 잘 되지 않는다.","subdomain":"긴장성 소화불량","subdomainEn":"Tension-Induced Dyspepsia","isReversed":false},{"id":5,"text":"중요한 날에는 속이 자주 불편하다.","subdomain":"긴장성 소화불량","subdomainEn":"Tension-Induced Dyspepsia","isReversed":false},{"id":6,"text":"스트레스를 받으면 복통이나 속쓰림이 심해진다.","subdomain":"스트레스성 복통","subdomainEn":"Stress-Related Abdominal Pain","isReversed":false},{"id":7,"text":"화가 나거나 억눌릴 때 배에 통증이 생긴다.","subdomain":"스트레스성 복통","subdomainEn":"Stress-Related Abdominal Pain","isReversed":false},{"id":8,"text":"걱정이 많을수록 위산이 올라오는 느낌이 든다.","subdomain":"스트레스성 복통","subdomainEn":"Stress-Related Abdominal Pain","isReversed":false},{"id":9,"text":"신경을 많이 쓰면 배가 묘하게 꼬이듯 아프다.","subdomain":"스트레스성 복통","subdomainEn":"Stress-Related Abdominal Pain","isReversed":false},{"id":10,"text":"긴장감이 심하면 구역질이나 울렁거림이 나타난다.","subdomain":"스트레스성 복통","subdomainEn":"Stress-Related Abdominal Pain","isReversed":false},{"id":11,"text":"식사시간을 자주 놓치거나 건너뛴다.","subdomain":"불규칙 식습관","subdomainEn":"Irregular Eating Pattern","isReversed":false},{"id":12,"text":"공부하느라 끼니를 거르는 일이 많다.","subdomain":"불규칙 식습관","subdomainEn":"Irregular Eating Pattern","isReversed":false},{"id":13,"text":"늦은 밤 야식이 일상화되어 있다.","subdomain":"불규칙 식습관","subdomainEn":"Irregular Eating Pattern","isReversed":false},{"id":14,"text":"불규칙한 식사로 배탈이나 위통이 자주 생긴다.","subdomain":"불규칙 식습관","subdomainEn":"Irregular Eating Pattern","isReversed":false},{"id":15,"text":"시험 기간에는 식사 패턴이 완전히 무너진다.","subdomain":"불규칙 식습관","subdomainEn":"Irregular Eating Pattern","isReversed":false},{"id":16,"text":"마음이 불안할 때 위나 배가 먼저 반응한다.","subdomain":"신체화 불안 반응","subdomainEn":"Somatic Anxiety Response","isReversed":false},{"id":17,"text":"위장 통증이 심할 때 대부분 정신적으로도 예민하다.","subdomain":"신체화 불안 반응","subdomainEn":"Somatic Anxiety Response","isReversed":false},{"id":18,"text":"마음의 긴장이 풀리면 위장 증상이 완화된다.","subdomain":"신체화 불안 반응","subdomainEn":"Somatic Anxiety Response","isReversed":false},{"id":19,"text":"불안감이 클수록 복부 통증이 심해진다.","subdomain":"신체화 불안 반응","subdomainEn":"Somatic Anxiety Response","isReversed":false},{"id":20,"text":"감정의 기복이 위장 건강에 직접 영향을 준다고 느낀다.","subdomain":"신체화 불안 반응","subdomainEn":"Somatic Anxiety Response","isReversed":false}]'::jsonb
