) VALUES (
  'E-5',
  '집중력 결핍 증후군 검사',
  'E',
  '집중력 결핍 증후군',
  '학습 중 주의력 저하와 집중 유지 어려움의 정도를 측정합니다.',
  20,
  3,
  false,
  false,
  false,
  false,
  2900,
  '["감정적 분산","환경적 방해","습관적 부주의","낮은 자기조절"]'::jsonb,
  '[{"id":1,"text":"공부를 하다 보면 자꾸 다른 생각이 떠오른다.","subdomain":"감정적 분산","subdomainEn":"Emotional Distraction","isReversed":false},{"id":2,"text":"마음이 불안하거나 초조하면 집중이 거의 되지 않는다.","subdomain":"감정적 분산","subdomainEn":"Emotional Distraction","isReversed":false},{"id":3,"text":"감정기복이 심할 때 공부 흐름이 쉽게 끊긴다.","subdomain":"감정적 분산","subdomainEn":"Emotional Distraction","isReversed":false},{"id":4,"text":"성적이나 결과를 생각하면 불안해서 집중이 흐트러진다.","subdomain":"감정적 분산","subdomainEn":"Emotional Distraction","isReversed":false},{"id":5,"text":"공부 중에도 사소한 일에 예민하게 반응한다.","subdomain":"감정적 분산","subdomainEn":"Emotional Distraction","isReversed":false},{"id":6,"text":"공부 중 휴대폰이나 SNS를 자주 확인한다.","subdomain":"환경적 방해","subdomainEn":"Environmental Disruption","isReversed":false},{"id":7,"text":"주변 사람의 말소리나 움직임에 쉽게 집중이 깨진다.","subdomain":"환경적 방해","subdomainEn":"Environmental Disruption","isReversed":false},{"id":8,"text":"정리되지 않은 책상이나 공간에서 공부가 잘 안된다.","subdomain":"환경적 방해","subdomainEn":"Environmental Disruption","isReversed":false},{"id":9,"text":"집중이 안 될 때 유튜브나 음악으로 도피하는 편이다.","subdomain":"환경적 방해","subdomainEn":"Environmental Disruption","isReversed":false},{"id":10,"text":"학습 장소를 자주 바꾸는 편이다.","subdomain":"환경적 방해","subdomainEn":"Environmental Disruption","isReversed":false},{"id":11,"text":"공부를 시작해도 금세 딴 짓을 한다.","subdomain":"습관적 부주의","subdomainEn":"Habitual Inattention","isReversed":false},{"id":12,"text":"공부를 할 때 목표나 계획이 명확하지 않다.","subdomain":"습관적 부주의","subdomainEn":"Habitual Inattention","isReversed":false},{"id":13,"text":"작은 성취보다 즉각적인 자극(게임, 영상 등)에 끌린다.","subdomain":"습관적 부주의","subdomainEn":"Habitual Inattention","isReversed":false},{"id":14,"text":"같은 내용을 여러번 읽어도 내용이 잘 남지 않는다.","subdomain":"습관적 부주의","subdomainEn":"Habitual Inattention","isReversed":false},{"id":15,"text":"집중 유지 시간이 30분이상 어렵다.","subdomain":"습관적 부주의","subdomainEn":"Habitual Inattention","isReversed":false},{"id":16,"text":"스스로 집중이 안될 때, 이를 조절하기 어렵다.","subdomain":"낮은 자기조절","subdomainEn":"Low Self-Regulation","isReversed":false},{"id":17,"text":"해야 할 일을 알지만 자꾸 미루게 된다.","subdomain":"낮은 자기조절","subdomainEn":"Low Self-Regulation","isReversed":false},{"id":18,"text":"공부 도중 잠깐 쉴 때 시간을 조절하지 못한다.","subdomain":"낮은 자기조절","subdomainEn":"Low Self-Regulation","isReversed":false},{"id":19,"text":"계획을 세워도 지키지 못할 때가 많다.","subdomain":"낮은 자기조절","subdomainEn":"Low Self-Regulation","isReversed":false},{"id":20,"text":"집중이 흐트러졌을 때 다시 돌아오기 힘들다.","subdomain":"낮은 자기조절","subdomainEn":"Low Self-Regulation","isReversed":false}]'::jsonb
)
